package operators;

public class Assignment {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		int x=35;
		int y=15;
		
		//Additional and Assignment
		    x=x+5;
		    
		    System.out.println("X addition value is : "+x);
		    x+=8;
		    System.out.println("X addition value is : "+x);
		
		//Subraction and Assignment
		    
		    x=x-10;
		    System.out.println("value subraction of x is : "+x);
		    
		    x-=5;
		    System.out.println("value subraction  of x is  : "+x);
		    
		    
		    //multiplication and Assignment
		    
		    x=x*10;
		    System.out.println("value of multiplication x is : "+x);
		    
		    x*=5;
		    System.out.println("value of multiplication x is : "+x);
		    
		    
		    //Division and Assignment
		    
		    x=x/4;
		    System.out.println("value of division x is : "+x);
		    
		    x/=2;
		    System.out.println("value of division x is : "+x);
		    
		    
		    //Modulus and Assignment
		    
		    x=x%3;
		    System.out.println("value of modulus x is : "+x);

		    
		    x%=2;
		    System.out.println("value of modulus x is : "+x);
		
		

	}

}
